const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/schedule/calendar_items',
  headers: {'content-type': 'application/json'},
  body: {
    calendar_item: {
      assigned_id: 0,
      color: '#A4505D',
      description: 'Use some power tools to fix the drywall.',
      finish: '2020-02-02',
      name: 'Fix Drywall',
      percentage: 50,
      private: false,
      start: '2020-01-01'
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/schedule/calendar_items"),
    Content = new StringContent("{\"calendar_item\":{\"assigned_id\":0,\"color\":\"#A4505D\",\"description\":\"Use some power tools to fix the drywall.\",\"finish\":\"2020-02-02\",\"name\":\"Fix Drywall\",\"percentage\":50,\"private\":false,\"start\":\"2020-01-01\"}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

